//! Port of the translation system (`Translator`, `TranslationString`): the UI strings are
//! written in English and looked up in the catalog of the chosen language, falling back to
//! English when a string has no translation.
//!
//! The catalogs in `translations/` hold the upstream translations of the strings this port
//! shows. They are generated by `translations/update.py`, which matches the English text of
//! every `tr`/`trf`/`n_` literal in the sources with the upstream `.xlf` files; run it again
//! after adding or changing UI strings.

use std::collections::HashMap;
use std::fmt::Display;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Mutex, OnceLock};

/// A language the UI can be shown in. `name` is the value of the `translation` setting, as
/// upstream (`AppSettings.Translation`: the name of the translation file).
pub struct Language {
    pub name: &'static str,
    /// The name of the language in the language itself.
    pub native: &'static str,
    /// BCP 47 code (`AppSettings.CurrentLanguageCode`).
    pub code: &'static str,
    /// The script, when the default fonts can't draw it: a system font is loaded for it.
    pub script: Option<Script>,
    catalog: &'static str,
}

/// Scripts (or letters) missing from egui's built-in fonts.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Script {
    Japanese,
    Korean,
    SimplifiedChinese,
    TraditionalChinese,
    Thai,
    /// Latin with the stacked accents of Vietnamese (ế, ộ…).
    Vietnamese,
}

macro_rules! language {
    ($name:literal, $native:literal, $code:literal, $script:expr) => {
        Language { name: $name, native: $native, code: $code, script: $script, catalog: include_str!(concat!("../translations/", $code, ".json")) }
    };
}

/// The languages of upstream, English first. Upstream's right-to-left languages (Arabic,
/// Persian, Hebrew, Urdu) and Tamil are left out: egui lays text out left to right without
/// shaping, which garbles them.
pub static LANGUAGES: &[Language] = &[
    Language { name: "English", native: "English", code: "en", script: None, catalog: "{}" },
    language!("Czech", "Čeština", "cs", None),
    language!("Dutch", "Nederlands", "nl", None),
    language!("Finnish", "Suomi", "fi", None),
    language!("French", "Français", "fr", None),
    language!("German", "Deutsch", "de", None),
    language!("Croatian", "Hrvatski", "hr", None),
    language!("Hungarian", "Magyar", "hu", None),
    language!("Indonesian", "Bahasa Indonesia", "id", None),
    language!("Italian", "Italiano", "it", None),
    language!("Japanese", "日本語", "ja", Some(Script::Japanese)),
    language!("Korean", "한국어", "ko", Some(Script::Korean)),
    language!("Latvian", "Latviešu", "lv", None),
    language!("Norwegian", "Norsk", "no", None),
    language!("Polish", "Polski", "pl", None),
    language!("Portuguese", "Português", "pt-PT", None),
    language!("Portuguese (Brazil)", "Português (Brasil)", "pt-BR", None),
    language!("Romanian", "Română", "ro", None),
    language!("Russian", "Русский", "ru", None),
    language!("Serbian", "Српски", "sr", None),
    language!("Simplified Chinese", "简体中文", "zh-CN", Some(Script::SimplifiedChinese)),
    language!("Spanish", "Español", "es", None),
    language!("Spanish (Argentina)", "Español (Argentina)", "es-AR", None),
    language!("Swedish", "Svenska", "sv", None),
    language!("Thai", "ไทย", "th", Some(Script::Thai)),
    language!("Traditional Chinese", "繁體中文", "zh-TW", Some(Script::TraditionalChinese)),
    language!("Turkish", "Türkçe", "tr", None),
    language!("Ukrainian", "Українська", "uk", None),
    language!("Vietnamese", "Tiếng Việt", "vi", Some(Script::Vietnamese)),
];

impl Language {
    /// The name shown in language lists: in the language itself, and in English. Languages
    /// in a script the default fonts can't draw are named in English only (their font is only
    /// loaded once chosen).
    pub fn label(&self) -> String {
        if self.script.is_some() || self.native == self.name {
            self.name.to_string()
        } else if self.name.contains('(') {
            // "Português (Brasil)" rather than "Português (Brasil) (Portuguese (Brazil))"
            self.native.to_string()
        } else {
            format!("{} ({})", self.native, self.name)
        }
    }
}

/// The language of a `translation` setting; English when unknown or empty.
pub fn language(name: &str) -> &'static Language {
    LANGUAGES.iter().find(|l| l.name.eq_ignore_ascii_case(name)).unwrap_or(&LANGUAGES[0])
}

type Catalog = HashMap<String, String>;

/// Index in [`LANGUAGES`] of the language in use; `ENGLISH` when no translation is used.
static CURRENT: AtomicUsize = AtomicUsize::new(ENGLISH);
const ENGLISH: usize = usize::MAX;

/// The catalogs, by index in [`LANGUAGES`]: each is parsed once, when its language is chosen,
/// and kept for the life of the process, so `tr` needs no lock.
fn catalogs() -> &'static [OnceLock<Catalog>] {
    static CATALOGS: OnceLock<Vec<OnceLock<Catalog>>> = OnceLock::new();
    CATALOGS.get_or_init(|| LANGUAGES.iter().map(|_| OnceLock::new()).collect())
}

fn language_index(lang: &'static Language) -> usize {
    LANGUAGES.iter().position(|l| std::ptr::eq(l, lang)).unwrap_or(0)
}

fn catalog(lang: &'static Language) -> &'static Catalog {
    catalogs()[language_index(lang)].get_or_init(|| serde_json::from_str(lang.catalog).unwrap_or_default())
}

/// Shows the UI in a language (by its setting name); takes effect on the next frame.
pub fn set_language(name: &str) {
    let lang = language(name);
    let index = if lang.code == "en" {
        ENGLISH
    } else {
        catalog(lang);
        language_index(lang)
    };
    CURRENT.store(index, Ordering::Release);
}

/// The translation of a UI string, or the string itself when it has none.
pub fn tr(s: &str) -> &str {
    translate(CURRENT.load(Ordering::Acquire), s)
}

/// The translation of `s` in the language at `index` in [`LANGUAGES`] (`ENGLISH`: none).
fn translate(index: usize, s: &str) -> &str {
    if index == ENGLISH {
        return s;
    }
    match catalogs().get(index).and_then(OnceLock::get) {
        Some(catalog) => catalog.get(s).map_or(s, String::as_str),
        None => s,
    }
}

/// Translates a format string with `{0}`, `{1}`… placeholders (as upstream's
/// `TranslationString.Text` with `string.Format`) and fills them in.
pub fn trf(s: &str, args: &[&dyn Display]) -> String {
    format_args_into(tr(s), args)
}

/// Marks a string for translation where it is defined (a constant, a table) and translated
/// with `tr` where it is shown.
pub const fn n_(s: &'static str) -> &'static str {
    s
}

fn format_args_into(template: &str, args: &[&dyn Display]) -> String {
    let mut out = String::with_capacity(template.len() + 16);
    let mut rest = template;
    while let Some(open) = rest.find('{') {
        out.push_str(&rest[..open]);
        let after = &rest[open + 1..];
        let index = after.find('}').and_then(|close| after[..close].parse::<usize>().ok().map(|i| (i, close)));
        match index {
            Some((i, close)) if i < args.len() => {
                out.push_str(&args[i].to_string());
                rest = &after[close + 1..];
            }
            _ => {
                out.push('{');
                rest = after;
            }
        }
    }
    out.push_str(rest);
    out
}

/// Loads a system font for the script of `lang` as a fallback after egui's own fonts, so
/// that Chinese, Japanese, Korean, Thai and Vietnamese text is drawn. Does nothing for other languages,
/// or when no font is found (the text then shows as boxes).
pub fn install_fonts(ctx: &egui::Context, lang: &Language) {
    static INSTALLED: Mutex<Option<Script>> = Mutex::new(None);
    let mut installed = INSTALLED.lock().unwrap_or_else(|e| e.into_inner());
    if *installed == lang.script {
        return;
    }
    let mut fonts = egui::FontDefinitions::default();
    if let Some((data, index)) = lang.script.and_then(system_font) {
        let mut font = egui::FontData::from_owned(data);
        font.index = index;
        fonts.font_data.insert("script-fallback".into(), std::sync::Arc::new(font));
        for family in [egui::FontFamily::Proportional, egui::FontFamily::Monospace] {
            fonts.families.entry(family).or_default().push("script-fallback".into());
        }
    }
    ctx.set_fonts(fonts);
    *installed = lang.script;
}

/// Reads a system font covering `script`: the font file and the index of the face in it.
fn system_font(script: Script) -> Option<(Vec<u8>, u32)> {
    #[cfg(windows)]
    {
        let dir = std::path::PathBuf::from(std::env::var_os("WINDIR").unwrap_or_else(|| "C:\\Windows".into())).join("Fonts");
        let names: &[&str] = match script {
            Script::Japanese => &["YuGothM.ttc", "meiryo.ttc", "msgothic.ttc"],
            Script::Korean => &["malgun.ttf", "gulim.ttc"],
            Script::SimplifiedChinese => &["msyh.ttc", "simsun.ttc"],
            Script::TraditionalChinese => &["msjh.ttc", "mingliu.ttc"],
            Script::Thai => &["LeelawUI.ttf", "tahoma.ttf"],
            Script::Vietnamese => &["segoeui.ttf", "arial.ttf"],
        };
        names.iter().find_map(|n| std::fs::read(dir.join(n)).ok()).map(|d| (d, 0))
    }
    #[cfg(target_os = "macos")]
    {
        let paths: &[&str] = match script {
            Script::Japanese => &["/System/Library/Fonts/ヒラギノ角ゴシック W3.ttc", "/System/Library/Fonts/Hiragino Sans GB.ttc"],
            Script::Korean => &["/System/Library/Fonts/AppleSDGothicNeo.ttc"],
            Script::SimplifiedChinese | Script::TraditionalChinese => {
                &["/System/Library/Fonts/Hiragino Sans GB.ttc", "/System/Library/Fonts/STHeiti Light.ttc"]
            }
            Script::Thai => &["/System/Library/Fonts/Supplemental/Thonburi.ttc", "/System/Library/Fonts/Thonburi.ttc"],
            Script::Vietnamese => &["/System/Library/Fonts/Helvetica.ttc"],
        };
        paths
            .iter()
            .chain(["/System/Library/Fonts/Supplemental/Arial Unicode.ttf", "/Library/Fonts/Arial Unicode.ttf"].iter())
            .find_map(|p| std::fs::read(p).ok())
            .map(|d| (d, 0))
    }
    #[cfg(not(any(windows, target_os = "macos")))]
    {
        // fontconfig picks the font the desktop uses for the language
        let lang = match script {
            Script::Japanese => "ja",
            Script::Korean => "ko",
            Script::SimplifiedChinese => "zh-cn",
            Script::TraditionalChinese => "zh-tw",
            Script::Thai => "th",
            Script::Vietnamese => "vi",
        };
        let out = std::process::Command::new("fc-match").args(["-f", "%{file}\n%{index}", &format!(":lang={lang}")]).output().ok()?;
        let out = String::from_utf8_lossy(&out.stdout);
        let mut lines = out.lines();
        let file = lines.next()?.trim();
        let index = lines.next().and_then(|i| i.trim().parse().ok()).unwrap_or(0);
        std::fs::read(file).ok().map(|d| (d, index))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // `CURRENT` is global and other tests check English texts: the tests read catalogs
    // directly instead of switching the language.

    #[test]
    fn looks_up_catalogs_and_falls_back_to_english() {
        assert_eq!(catalog(language("German")).get("Cancel").map(String::as_str), Some("Abbrechen"));
        assert_eq!(catalog(language("french")).get("Cancel").map(String::as_str), Some("Annuler"));
        assert_eq!(language("Klingon").code, "en");
        assert_eq!(language("").code, "en");
        // English: nothing is translated
        assert_eq!(tr("Cancel"), "Cancel");
        // what `tr` returns once a language is chosen; untranslated strings stay English
        let german = language_index(language("German"));
        assert_eq!(translate(german, "Cancel"), "Abbrechen");
        assert_eq!(translate(german, "not a UI string"), "not a UI string");
        assert_eq!(translate(ENGLISH, "Cancel"), "Cancel");
        assert_eq!(trf("{0} of {1}", &[&1, &3]), "1 of 3");
    }

    #[test]
    fn fills_placeholders() {
        let name = "main";
        assert_eq!(format_args_into("Delete branch {0}?", &[&name]), "Delete branch main?");
        assert_eq!(format_args_into("{1} of {0}", &[&3, &1]), "1 of 3");
        // braces that are not placeholders stay
        assert_eq!(format_args_into("{x} {5} {", &[&1]), "{x} {5} {");
    }

    fn sources() -> Vec<(std::path::PathBuf, String)> {
        fn walk(dir: &std::path::Path, out: &mut Vec<(std::path::PathBuf, String)>) {
            for e in std::fs::read_dir(dir).unwrap().flatten() {
                let p = e.path();
                if p.is_dir() {
                    walk(&p, out);
                } else if p.extension().is_some_and(|x| x == "rs") {
                    out.push((p.clone(), std::fs::read_to_string(&p).unwrap()));
                }
            }
        }
        let mut out = Vec::new();
        walk(&std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src"), &mut out);
        out
    }

    /// The strings marked for translation in the sources, as `update.py` reads them.
    fn marked_strings() -> std::collections::HashSet<String> {
        let re = regex::Regex::new(r#"\b(?:tr|trf|n_)\(\s*"((?:[^"\\]|\\.)*)""#).unwrap();
        let mut set = std::collections::HashSet::new();
        for (path, text) in sources() {
            if path.ends_with("i18n.rs") {
                continue;
            }
            for c in re.captures_iter(&text) {
                set.insert(c[1].replace("\\n", "\n").replace("\\t", "\t").replace("\\\"", "\"").replace("\\\\", "\\"));
            }
        }
        set
    }

    fn placeholders(s: &str) -> Vec<String> {
        let re = regex::Regex::new(r"\{\d+\}").unwrap();
        let mut v: Vec<String> = re.find_iter(s).map(|m| m.as_str().to_string()).collect();
        v.sort();
        v.dedup();
        v
    }

    /// Every catalog parses, every entry is a string the sources still show (else run
    /// `translations/update.py`), and translations keep the placeholders of their source.
    #[test]
    fn catalogs_match_the_sources() {
        let marked = marked_strings();
        assert!(marked.len() > 300, "only {} strings are marked for translation", marked.len());
        for lang in LANGUAGES.iter().skip(1) {
            let map: HashMap<String, String> = serde_json::from_str(lang.catalog).unwrap_or_else(|e| panic!("{}: {e}", lang.code));
            assert!(map.len() > 100, "{} has only {} translations", lang.name, map.len());
            for (source, target) in &map {
                assert!(marked.contains(source), "{}: {source:?} is no longer shown; run translations/update.py", lang.code);
                assert_eq!(placeholders(source), placeholders(target), "{}: placeholders of {source:?} -> {target:?}", lang.code);
                assert!(!target.trim().is_empty(), "{}: empty translation of {source:?}", lang.code);
            }
        }
    }

    /// The catalogs on disk are the ones listed in `LANGUAGES`.
    #[test]
    fn every_catalog_file_is_listed() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("translations");
        let mut files: Vec<String> =
            std::fs::read_dir(dir).unwrap().flatten().filter_map(|e| e.file_name().to_str()?.strip_suffix(".json").map(str::to_string)).collect();
        files.sort();
        let mut listed: Vec<String> = LANGUAGES.iter().skip(1).map(|l| l.code.to_string()).collect();
        listed.sort();
        assert_eq!(files, listed);
    }

    /// Strings are marked for translation with string literals the scanner can read: `tr`
    /// of a `format!` result can't be in a catalog.
    #[test]
    fn no_translation_of_formatted_strings() {
        let re = regex::Regex::new(r"\btrf?\(\s*&?format!").unwrap();
        for (path, text) in sources() {
            if path.ends_with("i18n.rs") {
                continue;
            }
            assert!(!re.is_match(&text), "{}: use trf(\"… {{0}} …\", &[&x]) instead of tr(&format!(…))", path.display());
        }
    }
}
